CREATE TABLE IF NOT EXISTS workspaces (id text PRIMARY KEY, state jsonb NOT NULL, version integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS app_users (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, role text NOT NULL CHECK (role IN ('analyst','manager','warehouse','procurement','admin')), org_id text NOT NULL, password_hash text NOT NULL);
CREATE TABLE IF NOT EXISTS app_sessions (token_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES app_users(id), expires_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS session_user_idx ON app_sessions(user_id);
CREATE INDEX IF NOT EXISTS session_expiry_idx ON app_sessions(expires_at);
CREATE TABLE IF NOT EXISTS suppliers (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), name text NOT NULL, data jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS supplier_workspace_idx ON suppliers(workspace_id);
CREATE TABLE IF NOT EXISTS warehouses (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), name text NOT NULL, capacity integer NOT NULL CHECK (capacity >= 0), data jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS warehouse_workspace_idx ON warehouses(workspace_id);
CREATE TABLE IF NOT EXISTS shipments (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), supplier_id text NOT NULL REFERENCES suppliers(id), warehouse_id text NOT NULL REFERENCES warehouses(id), quantity integer NOT NULL CHECK (quantity >= 0), eta timestamptz NOT NULL, data jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS shipment_workspace_idx ON shipments(workspace_id);
CREATE INDEX IF NOT EXISTS shipment_supplier_idx ON shipments(supplier_id);
CREATE INDEX IF NOT EXISTS shipment_warehouse_idx ON shipments(warehouse_id);
CREATE TABLE IF NOT EXISTS inventory_lots (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), warehouse_id text NOT NULL REFERENCES warehouses(id), item_id text NOT NULL, quantity integer NOT NULL CHECK(quantity >= 0), reserved integer NOT NULL CHECK(reserved >= 0 AND reserved <= quantity), status text NOT NULL CHECK(status IN ('available','quarantined','disputed')), data jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS lot_workspace_idx ON inventory_lots(workspace_id);
CREATE INDEX IF NOT EXISTS lot_warehouse_item_idx ON inventory_lots(warehouse_id,item_id);
CREATE TABLE IF NOT EXISTS customer_orders (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), warehouse_id text NOT NULL REFERENCES warehouses(id), deadline timestamptz NOT NULL, data jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS order_workspace_idx ON customer_orders(workspace_id);
CREATE INDEX IF NOT EXISTS order_warehouse_deadline_idx ON customer_orders(warehouse_id,deadline);
CREATE TABLE IF NOT EXISTS order_lines (id text PRIMARY KEY, order_id text NOT NULL REFERENCES customer_orders(id), item_id text NOT NULL, quantity integer NOT NULL CHECK(quantity > 0), fulfilled integer NOT NULL CHECK(fulfilled >= 0 AND fulfilled <= quantity));
CREATE INDEX IF NOT EXISTS line_order_idx ON order_lines(order_id);
